entries.body:
direction: right
style.fill: "#0a0e17"

classes: {
  layer: {
    style: {
      fill: "#121826"
      stroke: "#283450"
      font-color: "#9fb0d0"
    }
  }
  node: {
    style: {
      fill: "#1a2335"
      stroke: "#34425f"
      font-color: "#e8ecf5"
    }
  }
  store: {
    shape: cylinder
    style: {
      fill: "#121826"
      stroke: "#34425f"
      font-color: "#e8ecf5"
    }
  }
  hot: {
    style: {
      fill: "#6d7cff"
      stroke: "#4d5ae0"
      font-color: "#0a0e17"
    }
  }
}

edge: "Edge" {
  class: layer
  gw: "API gateway" { class: node }
  auth: "Auth + quota" { class: node }
  webhook: "Webhooks\nGitHub / Linear" { class: node }
}

orch: "Orchestrator" {
  class: layer
  planner: "Planner" { class: hot }
  queue: "Task queue" { class: node }
  sched: "Scheduler" { class: node }
}

agents: "Agent pool" {
  class: layer
  coder: "Coder agent" { class: node }
  tester: "Test agent" { class: node }
  reviewer: "Reviewer agent" { class: node }
}

exec: "Execution" {
  class: layer
  sandbox: "Sandbox runner" { class: node }
  repo: "Ephemeral repo" { class: node }
}

gates: "Quality gates" {
  class: layer
  evals: "Eval suite" { class: node }
  lint: "Lint + types" { class: node }
  security: "Security scan" { class: node }
}

delivery: "Delivery" {
  class: layer
  mq: "Merge queue" { class: hot }
  deploy: "Deploy" { class: node }
}

platform: "Platform services" {
  class: layer
  router: "Model router" { class: node }
  memory: "Vector memory" { class: store }
  obs: "Observability" { class: node }
  secrets: "Secrets" { class: store }
}

# primary spine — one clean left-to-right path
edge.gw -> orch.planner
orch.planner -> orch.queue
orch.queue -> orch.sched
orch.sched -> agents.coder
agents.coder -> agents.tester
agents.tester -> agents.reviewer
agents.coder -> exec.sandbox
exec.sandbox -> gates.evals
gates.evals -> gates.lint
gates.lint -> gates.security
gates.security -> agents.reviewer
agents.reviewer -> delivery.mq
delivery.mq -> delivery.deploy

# platform — minimal, container-level taps to avoid spaghetti
edge.auth -> orch.planner
agents -> platform.router
agents.coder -> platform.memory
exec.sandbox -> platform.secrets
delivery -> platform.obs

digraph AtlasEscalationTree {
  rankdir=TB;
  bgcolor="#0a0e17";
  splines=ortho;
  nodesep=0.6;
  ranksep=0.8;

  node [fontname="Helvetica", fontsize=11, fontcolor="#e8ecf5", color="#34425f"];
  edge [color="#5d6b86", fontcolor="#8b96ad", fontsize=9, arrowsize=0.7];

  // ── Start node ──────────────────────────────────────────────────────────────
  start [
    label="Agent completes task",
    shape=box, style="rounded,filled", fillcolor="#1a2335",
    fontsize=12, fontcolor="#c9d2e8"
  ];

  // ── Decision nodes (diamonds) ────────────────────────────────────────────────
  d1 [
    label="All quality gates\ngreen?\n(tests · lint · type-check)",
    shape=diamond, style=filled, fillcolor="#121826"
  ];

  d2 [
    label="Model confidence\n≥ threshold?\n(≥ 0.85)",
    shape=diamond, style=filled, fillcolor="#121826"
  ];

  d3 [
    label="Touches risk path?\n(auth · payments\n· infra · migrations)",
    shape=diamond, style=filled, fillcolor="#121826"
  ];

  d4 [
    label="Blast radius\nover limit?\n(> 400 LOC or > 12 files)",
    shape=diamond, style=filled, fillcolor="#121826"
  ];

  d5 [
    label="Prior reverts\nin this area?\n(last 90 days)",
    shape=diamond, style=filled, fillcolor="#121826"
  ];

  // ── Leaf outcomes ────────────────────────────────────────────────────────────
  auto_merge [
    label="Auto-merge",
    shape=box, style="rounded,filled",
    fillcolor="#2dd4a7", fontcolor="#06281c",
    fontsize=12, penwidth=2
  ];

  human_review [
    label="Human review",
    shape=box, style="rounded,filled",
    fillcolor="#f5b13d", fontcolor="#2a1c00",
    fontsize=12, penwidth=2
  ];

  halt_escalate [
    label="Halt + escalate",
    shape=box, style="rounded,filled",
    fillcolor="#ff5d6c", fontcolor="#2a0309",
    fontsize=12, penwidth=2
  ];

  // ── Edges ────────────────────────────────────────────────────────────────────
  start -> d1;

  // Gates failed → immediate halt
  d1 -> halt_escalate [label="no", color="#ff5d6c", fontcolor="#ff8a94"];
  d1 -> d2            [label="yes"];

  // Low confidence → human review
  d2 -> human_review  [label="no", color="#f5b13d", fontcolor="#f7c76a"];
  d2 -> d3            [label="yes"];

  // Risk path touched → always human review
  d3 -> human_review  [label="yes", color="#f5b13d", fontcolor="#f7c76a"];
  d3 -> d4            [label="no"];

  // Large blast radius → human review
  d4 -> human_review  [label="yes", color="#f5b13d", fontcolor="#f7c76a"];
  d4 -> d5            [label="no"];

  // Prior reverts in area → halt + escalate; otherwise auto-merge
  d5 -> halt_escalate [label="yes", color="#ff5d6c", fontcolor="#ff8a94"];
  d5 -> auto_merge    [label="no",  color="#2dd4a7", fontcolor="#56ddb8"];
}

