      {"week": "W02", "weekNum": 2, "prs": 23, "passRate": 85.1},
      {"week": "W03", "weekNum": 3, "prs": 27, "passRate": 85.8},
      {"week": "W04", "weekNum": 4, "prs": 31, "passRate": 87.3},
      {"week": "W05", "weekNum": 5, "prs": 38, "passRate": 88.0},
      {"week": "W06", "weekNum": 6, "prs": 42, "passRate": 89.4},
      {"week": "W07", "weekNum": 7, "prs": 49, "passRate": 90.7},
      {"week": "W08", "weekNum": 8, "prs": 53, "passRate": 91.5},
      {"week": "W09", "weekNum": 9, "prs": 58, "passRate": 92.1},
      {"week": "W10", "weekNum": 10, "prs": 62, "passRate": 93.3},
      {"week": "W11", "weekNum": 11, "prs": 67, "passRate": 94.0},
      {"week": "W12", "weekNum": 12, "prs": 71, "passRate": 94.8}
    ]
  },
  "encoding": {
    "x": {
      "field": "week",
      "type": "ordinal",
      "sort": {"field": "weekNum"},
      "axis": {
        "labelColor": "#8b96ad",
        "titleColor": "#8b96ad",
        "gridColor": "#16203a",
        "domainColor": "#283450",
        "tickColor": "#283450",
        "title": "Week",
        "labelAngle": 0,
        "labelFontSize": 11
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "color": "#6d7cff",
        "opacity": 0.85,
        "cornerRadiusTopLeft": 3,
        "cornerRadiusTopRight": 3
      },
      "encoding": {
        "y": {
          "field": "prs",
          "type": "quantitative",
          "axis": {
            "title": "PRs Merged",
            "titleColor": "#6d7cff",
            "labelColor": "#8b96ad",
            "gridColor": "#16203a",
            "domainColor": "#283450",
            "tickColor": "#283450",
            "labelFontSize": 10,
            "titleFontSize": 11
          },
          "scale": {"domain": [0, 90]}
        },
        "tooltip": [
          {"field": "week", "type": "ordinal", "title": "Week"},
          {"field": "prs", "type": "quantitative", "title": "PRs Merged"},
          {"field": "passRate", "type": "quantitative", "title": "Pass Rate %", "format": ".1f"}
        ]
      }
    },
    {
      "mark": {
        "type": "line",
        "color": "#2dd4a7",
        "strokeWidth": 2.5,
        "interpolate": "monotone"
      },
      "encoding": {
        "y": {
          "field": "passRate",
          "type": "quantitative",
          "axis": {
            "title": "Pass rate %",
            "titleColor": "#2dd4a7",
            "titlePadding": 10,
            "labelColor": "#8b96ad",
            "gridColor": "transparent",
            "domainColor": "#283450",
            "tickColor": "#283450",
            "labelFontSize": 10,
            "titleFontSize": 11,
            "format": ".0f",
            "labelExpr": "datum.value + '%'"
          },
          "scale": {"domain": [80, 100]}
        }
      }
    },
    {
      "mark": {
        "type": "point",
        "color": "#2dd4a7",
        "filled": true,
        "size": 55,
        "strokeWidth": 0
      },
      "encoding": {
        "y": {
          "field": "passRate",
          "type": "quantitative",
          "axis": null,
          "scale": {"domain": [80, 100]}
        }
      }
    }
  ],
  "resolve": {
    "scale": {"y": "independent"}
  },
  "config": {
    "view": {"stroke": null},
    "axis": {
      "labelColor": "#8b96ad",
      "titleColor": "#8b96ad",
      "gridColor": "#16203a",
      "domainColor": "#283450",
      "tickColor": "#283450"
    },
    "background": "#0a0e17"
  }
}
